insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('23a2c241-b5c6-5704-9e18-8478b42a8496', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '548', '‏ ‏حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏وَأَبُو بَكْرِ بْنُ إِسْحَقَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا وَقَالَ ‏ ‏ابْنُ مَنْصُورٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ الرَّبِيعِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏أَبَا الْخَيْرِ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏رَأَيْتُ عَلَى ‏ ‏ابْنِ وَعْلَةَ السَّبَإِيِّ ‏ ‏فَرْوًا فَمَسِسْتُهُ فَقَالَ مَا لَكَ تَمَسُّهُ قَدْ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏قُلْتُ ‏ ‏إِنَّا نَكُونُ ‏ ‏بِالْمَغْرِبِ ‏ ‏وَمَعَنَا ‏ ‏الْبَرْبَرُ ‏ ‏وَالْمَجُوسُ ‏ ‏نُؤْتَى بِالْكَبْشِ قَدْ ذَبَحُوهُ وَنَحْنُ لَا نَأْكُلُ ذَبَائِحَهُمْ وَيَأْتُونَا ‏ ‏بِالسِّقَاءِ ‏ ‏يَجْعَلُونَ فِيهِ ‏ ‏الْوَدَكَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَدْ سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏دِبَاغُهُ ‏ ‏طَهُورُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74ad4e46-ce77-525b-9757-5262d38cfc14', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '549', '‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏وَأَبُو بَكْرِ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الرَّبِيعِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏حَدَّثَهُ قَالَ حَدَّثَنِي ‏ ‏ابْنُ وَعْلَةَ السَّبَإِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏قُلْتُ ‏ ‏إِنَّا نَكُونُ ‏ ‏بِالْمَغْرِبِ ‏ ‏فَيَأْتِينَا ‏ ‏الْمَجُوسُ ‏ ‏بِالْأَسْقِيَةِ ‏ ‏فِيهَا الْمَاءُ ‏ ‏وَالْوَدَكُ ‏ ‏فَقَالَ اشْرَبْ فَقُلْتُ أَرَأْيٌ تَرَاهُ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏دِبَاغُهُ ‏ ‏طَهُورُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a26a4679-408a-5d9a-83a6-a856bf3fbdc9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '550', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ حَتَّى إِذَا كُنَّا ‏ ‏بِالْبَيْدَاءِ ‏ ‏أَوْ ‏ ‏بِذَاتِ الْجَيْشِ ‏ ‏انْقَطَعَ عِقْدٌ لِي فَأَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْتِمَاسِهِ وَأَقَامَ النَّاسُ مَعَهُ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَأَتَى النَّاسُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالُوا أَلَا ‏ ‏تَرَى إِلَى مَا صَنَعَتْ ‏ ‏عَائِشَةُ ‏ ‏أَقَامَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِالنَّاسِ مَعَهُ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي قَدْ نَامَ فَقَالَ حَبَسْتِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسَ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ قَالَتْ فَعَاتَبَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ وَجَعَلَ يَطْعُنُ بِيَدِهِ فِي خَاصِرَتِي فَلَا يَمْنَعُنِي مِنْ التَّحَرُّكِ إِلَّا مَكَانُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي فَنَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَصْبَحَ عَلَى غَيْرِ مَاءٍ فَأَنْزَلَ اللَّهُ آيَةَ التَّيَمُّمِ فَتَيَمَّمُوا فَقَالَ ‏ ‏أُسَيْدُ بْنُ الْحُضَيْرِ ‏ ‏وَهُوَ أَحَدُ النُّقَبَاءِ مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ فَوَجَدْنَا الْعِقْدَ تَحْتَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('185d209a-fc27-56cb-b23d-07377dabffa6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '551', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَابْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا اسْتَعَارَتْ مِنْ ‏ ‏أَسْمَاءَ ‏ ‏قِلَادَةً ‏ ‏فَهَلَكَتْ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاسًا مِنْ أَصْحَابِهِ فِي طَلَبِهَا فَأَدْرَكَتْهُمْ الصَّلَاةُ فَصَلَّوْا بِغَيْرِ وُضُوءٍ فَلَمَّا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَكَوْا ذَلِكَ إِلَيْهِ فَنَزَلَتْ آيَةُ التَّيَمُّمِ فَقَالَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏جَزَاكِ اللَّهُ خَيْرًا فَوَاللَّهِ مَا نَزَلَ بِكِ أَمْرٌ قَطُّ إِلَّا جَعَلَ اللَّهُ لَكِ مِنْهُ مَخْرَجًا وَجَعَلَ لِلْمُسْلِمِينَ فِيهِ بَرَكَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('29854a08-6d4a-5bf0-86c3-3b841d9cffa4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '552', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَرَأَيْتَ لَوْ أَنَّ رَجُلًا أَجْنَبَ فَلَمْ يَجِدْ الْمَاءَ شَهْرًا كَيْفَ يَصْنَعُ بِالصَّلَاةِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا يَتَيَمَّمُ وَإِنْ لَمْ يَجِدْ الْمَاءَ شَهْرًا فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏فَكَيْفَ بِهَذِهِ الْآيَةِ فِي سُورَةِ ‏ ‏الْمَائِدَةِ ‏ { ‏فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا ‏} ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَوْ رُخِّصَ لَهُمْ فِي هَذِهِ الْآيَةِ لَأَوْشَكَ إِذَا بَرَدَ عَلَيْهِمْ الْمَاءُ أَنْ يَتَيَمَّمُوا ‏ ‏بِالصَّعِيدِ ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏أَلَمْ تَسْمَعْ قَوْلَ ‏ ‏عَمَّارٍ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَأَجْنَبْتُ فَلَمْ أَجِدْ الْمَاءَ فَتَمَرَّغْتُ فِي ‏ ‏الصَّعِيدِ ‏ ‏كَمَا تَمَرَّغُ الدَّابَّةُ ثُمَّ أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ أَنْ تَقُولَ بِيَدَيْكَ هَكَذَا ثُمَّ ضَرَبَ بِيَدَيْهِ الْأَرْضَ ضَرْبَةً وَاحِدَةً ثُمَّ مَسَحَ الشِّمَالَ عَلَى الْيَمِينِ وَظَاهِرَ كَفَّيْهِ وَوَجْهَهُ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَوَلَمْ تَرَ ‏ ‏عُمَرَ ‏ ‏لَمْ يَقْنَعْ بِقَوْلِ ‏ ‏عَمَّارٍ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏وَسَاقَ الْحَدِيثَ بِقِصَّتِهِ نَحْوَ حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏غَيْرَ أَنَّهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا كَانَ يَكْفِيكَ أَنْ تَقُولَ هَكَذَا وَضَرَبَ بِيَدَيْهِ إِلَى الْأَرْضِ فَنَفَضَ يَدَيْهِ فَمَسَحَ وَجْهَهُ وَكَفَّيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2780c5bc-2077-52e3-a4b8-ba09447421a3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '553', '‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ هَاشِمٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ الْقَطَّانَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ ‏ ‏إِنِّي أَجْنَبْتُ فَلَمْ أَجِدْ مَاءً فَقَالَ لَا تُصَلِّ ‏ ‏فَقَالَ ‏ ‏عَمَّارٌ ‏ ‏أَمَا تَذْكُرُ يَا أَمِيرَ الْمُؤْمِنِينَ إِذْ أَنَا وَأَنْتَ فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَأَجْنَبْنَا فَلَمْ نَجِدْ مَاءً فَأَمَّا أَنْتَ فَلَمْ تُصَلِّ وَأَمَّا أَنَا فَتَمَعَّكْتُ فِي التُّرَابِ وَصَلَّيْتُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ أَنْ تَضْرِبَ بِيَدَيْكَ الْأَرْضَ ثُمَّ تَنْفُخَ ثُمَّ تَمْسَحَ بِهِمَا وَجْهَكَ وَكَفَّيْكَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏اتَّقِ اللَّهَ يَا ‏ ‏عَمَّارُ ‏ ‏قَالَ إِنْ شِئْتَ لَمْ أُحَدِّثْ بِهِ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏ابْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏ذَرٍّ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏سَلَمَةُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏فِي هَذَا الْإِسْنَادِ الَّذِي ذَكَرَ ‏ ‏الْحَكَمُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏نُوَلِّيكَ مَا تَوَلَّيْتَ ‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ شُمَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَرًّا ‏ ‏عَنْ ‏ ‏ابْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏قَالَ قَالَ ‏ ‏الْحَكَمُ ‏ ‏وَقَدْ ‏ ‏سَمِعْتَهُ مِنْ ‏ ‏ابْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ إِنِّي أَجْنَبْتُ فَلَمْ أَجِدْ مَاءً ‏ ‏وَسَاقَ الْحَدِيثَ وَزَادَ فِيهِ قَالَ ‏ ‏عَمَّارٌ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ إِنْ شِئْتَ ‏ ‏لِمَا جَعَلَ اللَّهُ عَلَيَّ مِنْ حَقِّكَ ‏ ‏لَا أُحَدِّثُ بِهِ أَحَدًا ‏ ‏وَلَمْ يَذْكُرْ حَدَّثَنِي ‏ ‏سَلَمَةُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab7d24b1-d8be-5c3c-bcc9-93c998bef054', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '554', '‏ ‏قَالَ ‏ ‏مُسْلِم ‏ ‏وَرَوَى ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏أَقْبَلْتُ أَنَا ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى دَخَلْنَا عَلَى ‏ ‏أَبِي الْجَهْمِ بْنِ الْحَارِثِ بْنِ الصِّمَّةِ الْأَنْصَارِيِّ ‏ ‏فَقَالَ ‏ ‏أَبُو الْجَهْمِ ‏ ‏أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَحْوِ ‏ ‏بِئْرِ جَمَلٍ ‏ ‏فَلَقِيَهُ رَجُلٌ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِ حَتَّى أَقْبَلَ عَلَى الْجِدَارِ فَمَسَحَ وَجْهَهُ وَيَدَيْهِ ثُمَّ رَدَّ عَلَيْهِ السَّلَامَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a8db1776-3f01-5bc0-ae87-5e4e7c9da181', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '555', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا مَرَّ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبُولُ فَسَلَّمَ فَلَمْ يَرُدَّ عَلَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f181ce55-f53f-53bb-adda-d46b20e401d5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '556', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏حَدَّثَنَا ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ لَقِيَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏وَهُوَ جُنُبٌ ‏ ‏فَانْسَلَّ ‏ ‏فَذَهَبَ فَاغْتَسَلَ فَتَفَقَّدَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا جَاءَهُ قَالَ أَيْنَ كُنْتَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ لَقِيتَنِي وَأَنَا جُنُبٌ فَكَرِهْتُ أَنْ أُجَالِسَكَ حَتَّى أَغْتَسِلَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يَنْجُسُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4f818983-52b8-5d83-88af-cd066d3a749c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '557', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَهُ وَهُوَ جُنُبٌ ‏ ‏فَحَادَ ‏ ‏عَنْهُ فَاغْتَسَلَ ثُمَّ جَاءَ فَقَالَ كُنْتُ جُنُبًا قَالَ ‏ ‏إِنَّ الْمُسْلِمَ لَا يَنْجُسُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5151b239-42fa-51ec-a02c-964e4d6784c7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '558', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَإِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ اللَّهَ عَلَى كُلِّ أَحْيَانِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fe2c5d50-f50c-5c21-ac1f-e05bf63967a1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '559', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏وَأَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏وَقَالَ ‏ ‏أَبُو الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ الْخَلَاءِ فَأُتِيَ بِطَعَامٍ فَذَكَرُوا لَهُ الْوُضُوءَ فَقَالَ ‏ ‏أُرِيدُ أَنْ أُصَلِّيَ فَأَتَوَضَّأَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a5ceaf37-9f36-5589-ac9b-d0623bf1c9c1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '560', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُا ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ مِنْ ‏ ‏الْغَائِطِ ‏ ‏وَأُتِيَ بِطَعَامٍ فَقِيلَ لَهُ أَلَا تَوَضَّأُ فَقَالَ ‏ ‏لِمَ ‏ ‏أَأُصَلِّي فَأَتَوَضَّأَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a2b5dc45-faf2-504d-a444-0c1689ea6ad6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '561', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏مَوْلَى آلِ ‏ ‏السَّائِبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْغَائِطِ ‏ ‏فَلَمَّا جَاءَ قُدِّمَ لَهُ طَعَامٌ فَقِيلَ يَا رَسُولَ اللَّهِ أَلَا تَوَضَّأُ قَالَ ‏ ‏لِمَ أَلِلصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fbeda7a1-7113-59ec-ad4c-778a784bbd45', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '562', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَبَّادِ بْنِ جَبَلَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ حُوَيْرِثٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُا ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى حَاجَتَهُ مِنْ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ فَأَكَلَ وَلَمْ يَمَسَّ مَاءً ‏ ‏قَالَ ‏ ‏وَزَادَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ لَهُ ‏ ‏إِنَّكَ لَمْ تَوَضَّأْ قَالَ مَا أَرَدْتُ صَلَاةً فَأَتَوَضَّأَ ‏ ‏وَزَعَمَ ‏ ‏عَمْرٌو ‏ ‏أَنَّهُ سَمِعَ مِنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d173576-9ce2-5bd6-be8a-03895f9bfe05', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '563', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏أَيْضًا ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏فِي حَدِيثِ ‏ ‏حَمَّادٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ وَفِي حَدِيثِ ‏ ‏هُشَيْمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَخَلَ ‏ ‏الْكَنِيفَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَ أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('28533ff2-5d69-5535-a785-1aef7e27e695', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '564', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ ‏ ‏لِرَجُلٍ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبْدِ الْوَارِثِ ‏ ‏وَنَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنَاجِي ‏ ‏الرَّجُلَ فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى نَامَ الْقَوْمُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ce59d51-7f53-5fbe-b6d0-9b5710c12495', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '565', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنَاجِي رَجُلًا فَلَمْ يَزَلْ ‏ ‏يُنَاجِيهِ ‏ ‏حَتَّى نَامَ أَصْحَابُهُ ثُمَّ جَاءَ فَصَلَّى بِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4309df8-a1f9-53e1-81b2-c9a950a85121', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '566', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ وَهُوَ ابْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُا ‏ ‏كَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُونَ ثُمَّ يُصَلُّونَ وَلَا يَتَوَضَّئُونَ قَالَ قُلْتُ سَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ إِي وَاللَّهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71e7eaf3-a2ef-5acf-a1f2-8adf93a7d75d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '567', '‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ سَعِيدِ بْنِ صَخْرٍ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أُقِيمَتْ صَلَاةُ الْعِشَاءِ فَقَالَ رَجُلٌ لِي حَاجَةٌ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنَاجِيهِ ‏ ‏حَتَّى نَامَ الْقَوْمُ أَوْ بَعْضُ الْقَوْمِ ثُمَّ صَلَّوْا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af3b7cfd-801a-51de-ae82-e19ed068e1bb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '568', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏ح ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏يَجْتَمِعُونَ فَيَتَحَيَّنُونَ الصَّلَوَاتِ وَلَيْسَ يُنَادِي بِهَا أَحَدٌ فَتَكَلَّمُوا يَوْمًا فِي ذَلِكَ فَقَالَ بَعْضُهُمْ اتَّخِذُوا نَاقُوسًا مِثْلَ نَاقُوسِ ‏ ‏النَّصَارَى ‏ ‏وَقَالَ بَعْضُهُمْ قَرْنًا مِثْلَ قَرْنِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَوَلَا تَبْعَثُونَ رَجُلًا يُنَادِي بِالصَّلَاةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏قُمْ فَنَادِ بِالصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a41e11a-2f56-5aed-8e7c-c938c068ce25', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '569', '‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ يَشْفَعَ الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ ‏ ‏زَادَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُلَيَّةَ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏أَيُّوبَ ‏ ‏فَقَالَ ‏ ‏إِلَّا الْإِقَامَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95beaf80-a9e7-5642-b1e0-337590e4dcb0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '570', '‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏ذَكَرُوا أَنْ يُعْلِمُوا وَقْتَ الصَّلَاةِ بِشَيْءٍ يَعْرِفُونَهُ فَذَكَرُوا أَنْ يُنَوِّرُوا نَارًا أَوْ يَضْرِبُوا نَاقُوسًا ‏ ‏فَأُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏لَمَّا كَثُرَ النَّاسُ ذَكَرُوا أَنْ يُعْلِمُوا بِمِثْلِ حَدِيثِ ‏ ‏الثَّقَفِيِّ ‏ ‏غَيْرَ أَنَّهُ قَالَ أَنْ يُورُوا نَارًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f4e28895-4740-5d10-b8c5-24581cd99c03', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '571', '‏ ‏و حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ بْنُ سَعِيدٍ ‏ ‏وَعَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7e166c37-b976-51cd-8285-dc38bf0cd32e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '572', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ مَالِكُ بْنُ عَبْدِ الْوَاحِدِ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَبُو غَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏وَقَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ صَاحِبِ الدَّسْتَوَائِيِّ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ عَلَّمَهُ هَذَا الْأَذَانَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏ثُمَّ يَعُودُ فَيَقُولُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏حَيَّ عَلَى الصَّلَاةِ مَرَّتَيْنِ حَيَّ عَلَى الْفَلَاحِ مَرَّتَيْنِ ‏ ‏زَادَ ‏ ‏إِسْحَقُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75758c5f-ad40-51d6-a038-6f79d6f4a04e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '573', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤَذِّنَانِ ‏ ‏بِلَالٌ ‏ ‏وَابْنُ أُمِّ مَكْتُومٍ ‏ ‏الْأَعْمَى ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8a9678ed-d282-5c9f-8a6c-99dc8c3dd322', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '574', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏يُؤَذِّنُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ أَعْمَى ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ ‏ ‏وَسَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c939995-2676-586f-8f27-5a68b1039d9b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '575', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغِيرُ ‏ ‏إِذَا طَلَعَ الْفَجْرُ وَكَانَ يَسْتَمِعُ الْأَذَانَ فَإِنْ سَمِعَ أَذَانًا أَمْسَكَ وَإِلَّا ‏ ‏أَغَارَ ‏ ‏فَسَمِعَ رَجُلًا يَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْفِطْرَةِ ثُمَّ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجْتَ مِنْ النَّارِ فَنَظَرُوا فَإِذَا هُوَ رَاعِي مِعْزًى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6069e98e-d00f-57c9-b788-daef9323cc71', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '576', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bb85fc5-447a-58ed-9d9d-8ed7dd8c1581', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '577', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏حَيْوَةَ ‏ ‏وَسَعِيدِ بْنِ أَبِي أَيُّوبَ ‏ ‏وَغَيْرِهِمَا ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَمِعْتُمْ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ ثُمَّ صَلُّوا عَلَيَّ فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا ثُمَّ سَلُوا اللَّهَ لِي ‏ ‏الْوَسِيلَةَ فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ لَا ‏ ‏تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ فَمَنْ سَأَلَ لِي ‏ ‏الْوَسِيلَةَ ‏ ‏حَلَّتْ ‏ ‏لَهُ الشَّفَاعَةُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa3c08c5-ab3b-5627-b79c-b0d4708f604c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '578', '‏ ‏حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ جَهْضَمٍ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ إِسَافٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ أَحَدُكُمْ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ثُمَّ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ثُمَّ قَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏قَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏ثُمَّ قَالَ حَيَّ عَلَى الصَّلَاةِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ثُمَّ قَالَ حَيَّ عَلَى الْفَلَاحِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ثُمَّ قَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ قَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ثُمَّ قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ لَا إِلَهَ إِلَّا اللَّهُ مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f07ff53f-cd28-59b1-a47a-ffbefd0a0b85', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '579', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏الْحُكَيْمِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ الْقُرَشِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏الْحُكَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ ‏ ‏رَضِيتُ بِاللَّهِ رَبًّا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏رَسُولًا وَبِالْإِسْلَامِ دِينًا غُفِرَ لَهُ ذَنْبُهُ ‏ ‏قَالَ ‏ ‏ابْنُ رُمْحٍ ‏ ‏فِي رِوَايَتِهِ مَنْ قَالَ حِينَ يَسْمَعُ الْمُؤَذِّنَ وَأَنَا أَشْهَدُ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏قُتَيْبَةُ ‏ ‏قَوْلَهُ وَأَنَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2009d9ec-c23e-5f26-af03-fef4724068e3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '580', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏فَجَاءَهُ الْمُؤَذِّنُ يَدْعُوهُ إِلَى الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏سَمِعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c95130b9-57ed-5a65-b303-8cee867cbe47', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '581', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّيْطَانَ إِذَا سَمِعَ النِّدَاءَ بِالصَّلَاةِ ذَهَبَ حَتَّى يَكُونَ مَكَانَ ‏ ‏الرَّوْحَاءِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَسَأَلْتُهُ عَنْ ‏ ‏الرَّوْحَاءِ ‏ ‏فَقَالَ ‏ ‏هِيَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏سِتَّةٌ وَثَلَاثُونَ مِيلًا ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('10208177-a186-503f-9bdc-da6068829043', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '582', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَاللَّفْظُ ‏ ‏لِقُتَيْبَةَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ إِذَا سَمِعَ النِّدَاءَ بِالصَّلَاةِ ‏ ‏أَحَالَ ‏ ‏لَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ صَوْتَهُ فَإِذَا سَكَتَ رَجَعَ فَوَسْوَسَ فَإِذَا سَمِعَ الْإِقَامَةَ ذَهَبَ حَتَّى لَا يَسْمَعَ صَوْتَهُ فَإِذَا سَكَتَ رَجَعَ فَوَسْوَسَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('68997e32-010e-536c-995a-72b615030db5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '583', '‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَيَانٍ الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَذَّنَ الْمُؤَذِّنُ أَدْبَرَ الشَّيْطَانُ وَلَهُ ‏ ‏حُصَاصٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('17dab115-5329-5a3a-8f07-3a26a15eeb06', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '584', '‏ ‏حَدَّثَنِي ‏ ‏أُمَيَّةُ بْنُ بِسْطَامَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏أَبِي ‏ ‏إِلَى ‏ ‏بَنِي حَارِثَةَ ‏ ‏قَالَ وَمَعِي غُلَامٌ لَنَا ‏ ‏أَوْ صَاحِبٌ لَنَا ‏ ‏فَنَادَاهُ مُنَادٍ مِنْ حَائِطٍ بِاسْمِهِ قَالَ وَأَشْرَفَ الَّذِي مَعِي عَلَى الْحَائِطِ فَلَمْ يَرَ شَيْئًا فَذَكَرْتُ ذَلِكَ لِأَبِي فَقَالَ لَوْ شَعَرْتُ أَنَّكَ تَلْقَ هَذَا لَمْ أُرْسِلْكَ وَلَكِنْ إِذَا سَمِعْتَ صَوْتًا فَنَادِ بِالصَّلَاةِ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ أَنَّهُ قَالَ ‏ ‏إِنَّ الشَّيْطَانَ إِذَا نُودِيَ بِالصَّلَاةِ وَلَّى وَلَهُ ‏ ‏حُصَاصٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d3d9cf7c-7778-54b2-ba04-ab989caed36e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '585', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ يَعْنِي الْحِزَامِيَّ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ لَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ فَإِذَا قُضِيَ التَّأْذِينُ أَقْبَلَ حَتَّى إِذَا ثُوِّبَ بِالصَّلَاةِ أَدْبَرَ حَتَّى إِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ حَتَّى ‏ ‏يَخْطُرَ ‏ ‏بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ لَهُ اذْكُرْ كَذَا وَاذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ مِنْ قَبْلُ حَتَّى يَظَلَّ الرَّجُلُ مَا يَدْرِي كَمْ صَلَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ حَتَّى يَظَلَّ الرَّجُلُ إِنْ يَدْرِي كَيْفَ صَلَّى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a321cf58-4f5e-52e1-924d-f1f2ef8e0cf6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '586', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏وَسَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عُيَيْنَةَ ‏ ‏وَاللَّفْظُ ‏ ‏لِيَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ مَنْكِبَيْهِ وَقَبْلَ أَنْ يَرْكَعَ وَإِذَا رَفَعَ مِنْ الرُّكُوعِ وَلَا يَرْفَعُهُمَا بَيْنَ السَّجْدَتَيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ecca81f0-2d9a-530c-bd95-664dd0410b05', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '587', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ لِلصَّلَاةِ رَفَعَ يَدَيْهِ حَتَّى تَكُونَا ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ثُمَّ كَبَّرَ فَإِذَا أَرَادَ أَنْ يَرْكَعَ فَعَلَ مِثْلَ ذَلِكَ وَإِذَا رَفَعَ مِنْ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ وَلَا يَفْعَلُهُ حِينَ يَرْفَعُ رَأْسَهُ مِنْ السُّجُودِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ وَهُوَ ابْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ قُهْزَاذَ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ كَمَا ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏كَانَ رَسُولُ اللَّهِ إِذَا قَامَ لِلصَّلَاةِ رَفَعَ يَدَيْهِ حَتَّى تَكُونَا ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ثُمَّ كَبَّرَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
