insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('65c0607a-f67c-5f09-925b-8aa56b8aef41', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '589', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا كَبَّرَ رَفَعَ يَدَيْهِ حَتَّى ‏ ‏يُحَاذِيَ ‏ ‏بِهِمَا أُذُنَيْهِ وَإِذَا رَكَعَ رَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا أُذُنَيْهِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ فَقَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَعَلَ مِثْلَ ذَلِكَ ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏أَنَّهُ رَأَى نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ حَتَّى يُحَاذِيَ بِهِمَا فُرُوعَ أُذُنَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ac6ac90-da95-5381-b93c-38a620a5b796', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '590', '‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ ‏ ‏يُصَلِّي لَهُمْ فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ فَلَمَّا انْصَرَفَ قَالَ وَاللَّهِ إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b5145da-4a6d-5a59-8f9b-89bebbc61131', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '591', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ ثُمَّ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ حِينَ يَرْفَعُ صُلْبَهُ مِنْ الرُّكُوعِ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ رَبَّنَا وَلَكَ الْحَمْدُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يَفْعَلُ مِثْلَ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا وَيُكَبِّرُ حِينَ يَقُومُ مِنْ الْمَثْنَى بَعْدَ الْجُلُوسِ ثُمَّ يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ بِمِثْلِ حَدِيثِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏وَلَمْ يَذْكُرْ قَوْلَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِنِّي أَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ حِينَ يَسْتَخْلِفُهُ ‏ ‏مَرْوَانُ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏إِذَا قَامَ لِلصَّلَاةِ الْمَكْتُوبَةِ كَبَّرَ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏وَفِي حَدِيثِهِ فَإِذَا قَضَاهَا وَسَلَّمَ أَقْبَلَ عَلَى أَهْلِ الْمَسْجِدِ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a2ec177-6c6a-51f2-9c56-470ed59dc408', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '592', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْرَانَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ ‏ ‏يُكَبِّرُ فِي الصَّلَاةِ كُلَّمَا رَفَعَ وَوَضَعَ فَقُلْنَا يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مَا هَذَا التَّكْبِيرُ قَالَ إِنَّهَا لَصَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bef1d184-411b-5aad-b8f9-220ddae42913', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '593', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ وَيُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1dece97d-a78c-5499-b9d7-df50e4cbc04c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '594', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَخَلَفُ بْنُ هِشَامٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ أَنَا ‏ ‏وَعِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏خَلْفَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏فَكَانَ إِذَا سَجَدَ كَبَّرَ وَإِذَا رَفَعَ رَأْسَهُ كَبَّرَ وَإِذَا نَهَضَ مِنْ الرَّكْعَتَيْنِ كَبَّرَ فَلَمَّا انْصَرَفْنَا مِنْ الصَّلَاةِ قَالَ أَخَذَ ‏ ‏عِمْرَانُ ‏ ‏بِيَدِي ثُمَّ قَالَ لَقَدْ ‏ ‏صَلَّى بِنَا هَذَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَدْ ذَكَّرَنِي هَذَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d9346cd-0f7c-5d10-ac06-762ef550cfa8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '595', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db2a5e83-61f3-5578-b960-1cb94b9f5773', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '596', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَحْمُودُ بْنُ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ لِمَنْ لَمْ يَقْتَرِئْ ‏ ‏بِأُمِّ الْقُرْآنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a37c74e5-08ed-5ef1-9339-acd41b20cbe9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '597', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏مَحْمُودَ بْنَ الرَّبِيعِ ‏ ‏الَّذِي مَجَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِهِ مِنْ بِئْرِهِمْ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُبَادَةَ بْنَ الصَّامِتِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏و حَدَّثَنَاه ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ وَزَادَ فَصَاعِدًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6853bb80-066d-5dab-94d9-efca7c584ad4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '598', '‏ ‏و حَدَّثَنَاه ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏ثَلَاثًا غَيْرُ تَمَامٍ فَقِيلَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏إِنَّا نَكُونُ وَرَاءَ الْإِمَامِ فَقَالَ اقْرَأْ بِهَا فِي نَفْسِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ تَعَالَى ‏ ‏قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ وَلِعَبْدِي مَا سَأَلَ فَإِذَا قَالَ الْعَبْدُ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏قَالَ اللَّهُ تَعَالَى حَمِدَنِي عَبْدِي وَإِذَا قَالَ ‏ { ‏الرَّحْمَنِ الرَّحِيمِ ‏} ‏قَالَ اللَّهُ تَعَالَى أَثْنَى عَلَيَّ عَبْدِي وَإِذَا قَالَ ‏ { ‏مَالِكِ يَوْمِ الدِّينِ ‏} ‏قَالَ مَجَّدَنِي عَبْدِي وَقَالَ مَرَّةً فَوَّضَ إِلَيَّ عَبْدِي فَإِذَا قَالَ ‏ { ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‏} ‏قَالَ هَذَا بَيْنِي وَبَيْنَ عَبْدِي وَلِعَبْدِي مَا سَأَلَ فَإِذَا قَالَ ‏ { ‏اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏قَالَ هَذَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏بِهِ ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏دَخَلْتُ عَلَيْهِ وَهُوَ مَرِيضٌ فِي بَيْتِهِ فَسَأَلْتُهُ أَنَا عَنْهُ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏أَنَّ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى بَنِي ‏ ‏عَبْدِ اللَّهِ بْنِ هِشَامِ بْنِ زُهْرَةَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاةً فَلَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏سُفْيَانَ ‏ ‏وَفِي حَدِيثِهِمَا قَالَ اللَّهُ تَعَالَى قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي ‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ جَعْفَرٍ الْمَعْقِرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏قَالَ سَمِعْتُ مِنْ ‏ ‏أَبِي ‏ ‏وَمِنْ ‏ ‏أَبِي السَّائِبِ ‏ ‏وَكَانَا جَلِيسَيْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏يَقُولُهَا ثَلَاثًا بِمِثْلِ حَدِيثِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2f678e6-ec07-50d3-a632-83651b7fa900', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '599', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَلَاةَ إِلَّا بِقِرَاءَةٍ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَمَا أَعْلَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْلَنَّاهُ لَكُمْ وَمَا أَخْفَاهُ أَخْفَيْنَاهُ لَكُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
