insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1e26029d-626a-5539-b149-43ea8349eebe', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '602', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ فَصَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّلَامَ قَالَ ‏ ‏ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ فَرَجَعَ الرَّجُلُ فَصَلَّى كَمَا كَانَ صَلَّى ثُمَّ جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْكَ السَّلَامُ ثُمَّ قَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ حَتَّى فَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ فَقَالَ الرَّجُلُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُحْسِنُ غَيْرَ هَذَا عَلِّمْنِي قَالَ إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنْ الْقُرْآنِ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ افْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا دَخَلَ الْمَسْجِدَ فَصَلَّى وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَاحِيَةٍ وَسَاقَا الْحَدِيثَ بِمِثْلِ هَذِهِ الْقِصَّةِ وَزَادَا فِيهِ إِذَا قُمْتَ إِلَى الصَّلَاةِ ‏ ‏فَأَسْبِغْ ‏ ‏الْوُضُوءَ ثُمَّ اسْتَقْبِلْ الْقِبْلَةَ فَكَبِّرْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('56b81e91-df23-5baa-8211-ee7376e25573', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '603', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الظُّهْرِ ‏ ‏أَوْ الْعَصْرِ ‏ ‏فَقَالَ ‏ ‏أَيُّكُمْ قَرَأَ خَلْفِي ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏فَقَالَ رَجُلٌ أَنَا وَلَمْ أُرِدْ بِهَا إِلَّا الْخَيْرَ قَالَ قَدْ عَلِمْتُ أَنَّ بَعْضَكُمْ ‏ ‏خَالَجَنِيهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c10ac59f-24f8-545e-93a0-24d209cbc113', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '604', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ فَجَعَلَ رَجُلٌ يَقْرَأُ خَلْفَهُ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏فَلَمَّا انْصَرَفَ قَالَ ‏ ‏أَيُّكُمْ قَرَأَ ‏ ‏أَوْ أَيُّكُمْ الْقَارِئُ ‏ ‏فَقَالَ رَجُلٌ أَنَا فَقَالَ قَدْ ظَنَنْتُ أَنَّ بَعْضَكُمْ ‏ ‏خَالَجَنِيهَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَقَالَ قَدْ عَلِمْتُ أَنَّ بَعْضَكُمْ ‏ ‏خَالَجَنِيهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a5c2ac74-805b-5c6b-8236-4b53e0a63818', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '605', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏غُنْدَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقْرَأُ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏وَزَادَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏أَسَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَعَمْ وَنَحْنُ سَأَلْنَاهُ عَنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('358309f6-73d4-5a30-b47c-db873b7912a7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '606', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْرَانَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏كَانَ يَجْهَرُ بِهَؤُلَاءِ الْكَلِمَاتِ يَقُولُ سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ تَبَارَكَ اسْمُكَ وَتَعَالَى ‏ ‏جَدُّكَ ‏ ‏وَلَا إِلَهَ غَيْرُكَ ‏ ‏وَعَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّهُ كَتَبَ إِلَيْهِ يُخْبِرُهُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏قَالَ صَلَّيْتُ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَكَانُوا يَسْتَفْتِحُونَ ‏ ‏بِ ‏ { ‏الْحَمْد لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏لَا يَذْكُرُونَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏فِي أَوَّلِ قِرَاءَةٍ وَلَا فِي آخِرِهَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْرَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْحَقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَذْكُرُ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2a3f0be-e028-555f-a4a8-8c60db61bba7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '607', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ بَيْنَ أَظْهُرِنَا إِذْ أَغْفَى إِغْفَاءَةً ثُمَّ رَفَعَ رَأْسَهُ مُتَبَسِّمًا فَقُلْنَا مَا أَضْحَكَكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أُنْزِلَتْ عَلَيَّ ‏ ‏آنِفًا ‏ ‏سُورَةٌ فَقَرَأَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ { ‏إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ فَصَلِّ لِرَبِّكَ وَانْحَرْ إِنَّ ‏ ‏شَانِئَكَ ‏ ‏هُوَ ‏ ‏الْأَبْتَرُ ‏ } ‏ثُمَّ قَالَ أَتَدْرُونَ مَا الْكَوْثَرُ فَقُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّهُ نَهْرٌ وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ عَلَيْهِ خَيْرٌ كَثِيرٌ هُوَ حَوْضٌ تَرِدُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ آنِيَتُهُ عَدَدُ النُّجُومِ ‏ ‏فَيُخْتَلَجُ ‏ ‏الْعَبْدُ مِنْهُمْ فَأَقُولُ رَبِّ إِنَّهُ مِنْ أُمَّتِي فَيَقُولُ مَا تَدْرِي مَا أَحْدَثَتْ بَعْدَكَ ‏ ‏زَادَ ‏ ‏ابْنُ حُجْرٍ ‏ ‏فِي حَدِيثِهِ بَيْنَ أَظْهُرِنَا فِي الْمَسْجِدِ وَقَالَ مَا أَحْدَثَ بَعْدَكَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُا ‏ ‏أَغْفَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِغْفَاءَةً بِنَحْوِ حَدِيثِ ‏ ‏ابْنِ مُسْهِرٍ ‏ ‏غَيْرَ أَنَّهُ قَالَ نَهْرٌ وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ فِي الْجَنَّةِ عَلَيْهِ حَوْضٌ وَلَمْ يَذْكُرْ آنِيَتُهُ عَدَدُ النُّجُومِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f04dae1e-1189-5927-bf0c-42df9a8e65b2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '608', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْجَبَّارِ بْنُ وَائِلٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏وَمَوْلًى لَهُمْ ‏ ‏أَنَّهُمَا حَدَّثَاهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏وَائِلِ بْنِ حُجْرٍ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَ يَدَيْهِ حِينَ دَخَلَ فِي الصَّلَاةِ كَبَّرَ ‏ ‏وَصَفَ ‏ ‏هَمَّامٌ ‏ ‏حِيَالَ أُذُنَيْهِ ‏ ‏ثُمَّ الْتَحَفَ بِثَوْبِهِ ثُمَّ وَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى فَلَمَّا أَرَادَ أَنْ يَرْكَعَ أَخْرَجَ يَدَيْهِ مِنْ الثَّوْبِ ثُمَّ رَفَعَهُمَا ثُمَّ كَبَّرَ فَرَكَعَ فَلَمَّا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَفَعَ يَدَيْهِ فَلَمَّا سَجَدَ سَجَدَ بَيْنَ كَفَّيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2cbad6fa-1b85-5c32-a97d-29f9b0612c8f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '609', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَقُولُ فِي الصَّلَاةِ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّلَامُ عَلَى اللَّهِ السَّلَامُ عَلَى فُلَانٍ فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا قَعَدَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِذَا قَالَهَا أَصَابَتْ كُلَّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ ‏ ‏ثُمَّ يَتَخَيَّرُ مِنْ الْمَسْأَلَةِ مَا شَاءَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ وَلَمْ يَذْكُرْ ثُمَّ يَتَخَيَّرُ مِنْ الْمَسْأَلَةِ مَا شَاءَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَ حَدِيثِهِمَا وَذَكَرَ فِي الْحَدِيثِ ثُمَّ ‏ ‏لْيَتَخَيَّرْ بَعْدُ مِنْ الْمَسْأَلَةِ مَا شَاءَ أَوْ مَا أَحَبَّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جَلَسْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ بِمِثْلِ حَدِيثِ ‏ ‏مَنْصُورٍ ‏ ‏وَقَالَ ثُمَّ يَتَخَيَّرُ بَعْدُ مِنْ الدُّعَاءِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَيْفُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَخْبَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُا ‏ ‏عَلَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّشَهُّدَ كَفِّي بَيْنَ كَفَّيْهِ كَمَا يُعَلِّمُنِي السُّورَةَ مِنْ الْقُرْآنِ وَاقْتَصَّ التَّشَهُّدَ بِمِثْلِ مَا ‏ ‏اقْتَصُّوا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('186b3f57-a3be-512b-b4a9-22281b42d674', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '610', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏وَعَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنْ الْقُرْآنِ فَكَانَ يَقُولُ ‏ ‏التَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏وَفِي رِوَايَةِ ‏ ‏ابْنِ رُمْحٍ ‏ ‏كَمَا يُعَلِّمُنَا الْقُرْآنَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88560e91-0a8b-50c7-a657-f02145ff2c17', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '611', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنْ الْقُرْآنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6326ca01-7bd8-5de6-8a37-7fce6da8d223', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '612', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ الْأُمَوِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كَامِلٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏صَلَاةً فَلَمَّا كَانَ عِنْدَ الْقَعْدَةِ قَالَ رَجُلٌ مِنْ الْقَوْمِ أُقِرَّتْ الصَّلَاةُ ‏ ‏بِالْبِرِّ ‏ ‏وَالزَّكَاةِ قَالَ فَلَمَّا قَضَى ‏ ‏أَبُو مُوسَى ‏ ‏الصَّلَاةَ وَسَلَّمَ انْصَرَفَ فَقَالَ أَيُّكُمْ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا قَالَ ‏ ‏فَأَرَمَّ ‏ ‏الْقَوْمُ ثُمَّ قَالَ أَيُّكُمْ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا ‏ ‏فَأَرَمَّ ‏ ‏الْقَوْمُ فَقَالَ لَعَلَّكَ يَا ‏ ‏حِطَّانُ ‏ ‏قُلْتَهَا قَالَ مَا قُلْتُهَا وَلَقَدْ رَهِبْتُ أَنْ ‏ ‏تَبْكَعَنِي ‏ ‏بِهَا فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا قُلْتُهَا وَلَمْ أُرِدْ بِهَا إِلَّا الْخَيْرَ فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏أَمَا تَعْلَمُونَ كَيْفَ تَقُولُونَ فِي صَلَاتِكُمْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَنَا فَبَيَّنَ لَنَا سُنَّتَنَا وَعَلَّمَنَا صَلَاتَنَا فَقَالَ ‏ ‏إِذَا صَلَّيْتُمْ فَأَقِيمُوا صُفُوفَكُمْ ثُمَّ ‏ ‏لْيَؤُمَّكُمْ أَحَدُكُمْ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذْ قَالَ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ يُجِبْكُمْ اللَّهُ فَإِذَا كَبَّرَ وَرَكَعَ فَكَبِّرُوا وَارْكَعُوا فَإِنَّ الْإِمَامَ يَرْكَعُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتِلْكَ بِتِلْكَ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ يَسْمَعُ اللَّهُ لَكُمْ فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَإِذَا كَبَّرَ وَسَجَدَ فَكَبِّرُوا وَاسْجُدُوا فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتِلْكَ بِتِلْكَ وَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أَوَّلِ قَوْلِ أَحَدِكُمْ التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏كُلُّ هَؤُلَاءِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمِثْلِهِ ‏ ‏وَفِي حَدِيثِ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏مِنْ الزِّيَادَةِ وَإِذَا قَرَأَ فَأَنْصِتُوا وَلَيْسَ فِي حَدِيثِ أَحَدٍ مِنْهُمْ فَإِنَّ اللَّهَ قَالَ عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ‏ ‏إِلَّا فِي رِوَايَةِ ‏ ‏أَبِي كَامِلٍ ‏ ‏وَحْدَهُ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَقَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرِ ‏ ‏ابْنُ أُخْتِ ‏ ‏أَبِي النَّضْرِ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏فَقَالَ ‏ ‏مُسْلِمٌ ‏ ‏تُرِيدُ أَحْفَظَ مِنْ ‏ ‏سُلَيْمَانَ ‏ ‏فَقَالَ لَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَحَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَقَالَ هُوَ صَحِيحٌ ‏ ‏يَعْنِي ‏ ‏وَإِذَا قَرَأَ فَأَنْصِتُوا ‏ ‏فَقَالَ هُوَ عِنْدِي صَحِيحٌ ‏ ‏فَقَالَ لِمَ لَمْ تَضَعْهُ هَا هُنَا ‏ ‏قَالَ لَيْسَ كُلُّ شَيْءٍ عِنْدِي صَحِيحٍ وَضَعْتُهُ هَا هُنَا إِنَّمَا وَضَعْتُ هَا هُنَا مَا أَجْمَعُوا عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَ فِي الْحَدِيثِ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَضَى عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('152489f1-48bd-51d3-8e94-57705ef49e7e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '613', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏وَعَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏هُوَ الَّذِي كَانَ أُرِيَ النِّدَاءَ بِالصَّلَاةِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِي مَجْلِسِ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ لَهُ ‏ ‏بَشِيرُ بْنُ سَعْدٍ ‏ ‏أَمَرَنَا اللَّهُ تَعَالَى أَنَّ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ فَكَيْفَ نُصَلِّي عَلَيْكَ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ وَالسَّلَامُ كَمَا قَدْ عَلِمْتُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
