insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('871db560-6843-5f6e-8467-4d97ef8a01d5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '636', '‏ ‏حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَحَسَنٌ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏عَبْدٌ ‏ ‏أَخْبَرَنِي ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي لَهُمْ فِي وَجَعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تُوُفِّيَ فِيهِ حَتَّى إِذَا كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ وَهُمْ صُفُوفٌ فِي الصَّلَاةِ كَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتْرَ الْحُجْرَةِ فَنَظَرَ إِلَيْنَا وَهُوَ قَائِمٌ كَأَنَّ وَجْهَهُ وَرَقَةُ مُصْحَفٍ ثُمَّ تَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَاحِكًا قَالَ فَبُهِتْنَا وَنَحْنُ فِي الصَّلَاةِ مِنْ فَرَحٍ بِخُرُوجِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَكَصَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَلَى عَقِبَيْهِ لِيَصِلَ الصَّفَّ وَظَنَّ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَارِجٌ لِلصَّلَاةِ فَأَشَارَ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ أَنْ أَتِمُّوا صَلَاتَكُمْ قَالَ ثُمَّ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْخَى السِّتْرَ قَالَ فَتُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ يَوْمِهِ ذَلِكَ ‏ ‏و حَدَّثَنِيهِ ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَشَفَ السِّتَارَةَ يَوْمَ ‏ ‏الِاثْنَيْنِ بِهَذِهِ الْقِصَّةِ ‏ ‏وَحَدِيثُ ‏ ‏صَالِحٍ ‏ ‏أَتَمُّ وَأَشْبَعُ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ بِنَحْوِ حَدِيثِهِمَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('afd4e88e-3e9e-5997-b80e-d2c6baa853f9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '637', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَهَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمْ يَخْرُجْ إِلَيْنَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا فَأُقِيمَتْ الصَّلَاةُ فَذَهَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَتَقَدَّمُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحِجَابِ فَرَفَعَهُ فَلَمَّا وَضَحَ لَنَا وَجْهُ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَظَرْنَا مَنْظَرًا قَطُّ كَانَ أَعْجَبَ إِلَيْنَا مِنْ وَجْهِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَضَحَ لَنَا قَالَ ‏ ‏فَأَوْمَأَ ‏ ‏نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنْ يَتَقَدَّمَ وَأَرْخَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحِجَابَ فَلَمْ نَقْدِرْ عَلَيْهِ حَتَّى مَاتَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
