insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83fe16e5-da5a-54dd-9d8c-f19b628effc2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '639', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ إِلَى ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏لِيُصْلِحَ بَيْنَهُمْ ‏ ‏فَحَانَتْ ‏ ‏الصَّلَاةُ فَجَاءَ ‏ ‏الْمُؤَذِّنُ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَ أَتُصَلِّي بِالنَّاسِ فَأُقِيمُ قَالَ نَعَمْ قَالَ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ فِي الصَّلَاةِ ‏ ‏فَتَخَلَّصَ ‏ ‏حَتَّى وَقَفَ فِي الصَّفِّ فَصَفَّقَ النَّاسُ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لَا يَلْتَفِتُ فِي الصَّلَاةِ فَلَمَّا أَكْثَرَ النَّاسُ التَّصْفِيقَ الْتَفَتَ فَرَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَشَارَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ امْكُثْ مَكَانَكَ فَرَفَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَدَيْهِ فَحَمِدَ اللَّهَ عَزَّ وَجَلَّ عَلَى مَا أَمَرَهُ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ذَلِكَ ثُمَّ اسْتَأْخَرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَتَّى اسْتَوَى فِي الصَّفِّ وَتَقَدَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى ثُمَّ انْصَرَفَ فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَا مَنَعَكَ أَنْ تَثْبُتَ إِذْ أَمَرْتُكَ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَا كَانَ ‏ ‏لِابْنِ أَبِي قُحَافَةَ ‏ ‏أَنْ يُصَلِّيَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لِي رَأَيْتُكُمْ أَكْثَرْتُمْ التَّصْفِيقَ مَنْ نَابَهُ شَيْءٌ فِي صَلَاتِهِ فَلْيُسَبِّحْ فَإِنَّهُ إِذَا سَبَّحَ الْتُفِتَ إِلَيْهِ وَإِنَّمَا ‏ ‏التَّصْفِيحُ ‏ ‏لِلنِّسَاءِ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي حَازِمٍ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ الْقَارِيُّ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏مَالِكٍ ‏ ‏وَفِي حَدِيثِهِمَا ‏ ‏فَرَفَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَدَيْهِ فَحَمِدَ اللَّهَ وَرَجَعَ الْقَهْقَرَى وَرَاءَهُ حَتَّى قَامَ فِي الصَّفِّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ بَزِيعٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏قَالَ ‏ ‏ذَهَبَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْلِحُ بَيْنَ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏بِمِثْلِ حَدِيثِهِمْ وَزَادَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَقَ الصُّفُوفَ حَتَّى قَامَ عِنْدَ الصَّفِّ الْمُقَدَّمِ وَفِيهِ أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجَعَ الْقَهْقَرَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('073af12e-7f30-52d4-a8e9-3d0f2eb91cf9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '640', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ غَزَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَتَبَرَّزَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِبَلَ ‏ ‏الْغَائِطِ ‏ ‏فَحَمَلْتُ مَعَهُ ‏ ‏إِدَاوَةً ‏ ‏قَبْلَ صَلَاةِ الْفَجْرِ فَلَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ أَخَذْتُ ‏ ‏أُهَرِيقُ ‏ ‏عَلَى يَدَيْهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏وَغَسَلَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ يُخْرِجُ ‏ ‏جُبَّتَهُ ‏ ‏عَنْ ذِرَاعَيْهِ فَضَاقَ كُمَّا جُبَّتِهِ فَأَدْخَلَ يَدَيْهِ فِي ‏ ‏الْجُبَّةِ ‏ ‏حَتَّى أَخْرَجَ ذِرَاعَيْهِ مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏وَغَسَلَ ذِرَاعَيْهِ إِلَى الْمِرْفَقَيْنِ ثُمَّ تَوَضَّأَ عَلَى خُفَّيْهِ ثُمَّ أَقْبَلَ قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَأَقْبَلْتُ مَعَهُ حَتَّى نَجِدُ النَّاسَ قَدْ قَدَّمُوا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏فَصَلَّى لَهُمْ فَأَدْرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى الرَّكْعَتَيْنِ فَصَلَّى مَعَ النَّاسِ الرَّكْعَةَ الْآخِرَةَ فَلَمَّا سَلَّمَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتِمُّ صَلَاتَهُ فَأَفْزَعَ ذَلِكَ الْمُسْلِمِينَ فَأَكْثَرُوا التَّسْبِيحَ فَلَمَّا قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ أَقْبَلَ عَلَيْهِمْ ثُمَّ قَالَ ‏ ‏أَحْسَنْتُمْ أَوْ قَالَ ‏ ‏قَدْ أَصَبْتُمْ يَغْبِطُهُمْ أَنْ صَلَّوْا الصَّلَاةَ لِوَقْتِهَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَالْحُلْوَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ الْمُغِيرَةِ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏عَبَّادٍ ‏ ‏قَالَ ‏ ‏الْمُغِيرَةُ ‏ ‏فَأَرَدْتُ تَأْخِيرَ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c25a987-a20d-5c61-aa64-60078ec5280a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '641', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَحَرْمَلَةُ بْنُ يَحْيَى ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏ ‏زَادَ ‏ ‏حَرْمَلَةُ ‏ ‏فِي رِوَايَتِهِ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَقَدْ رَأَيْتُ رِجَالًا مِنْ أَهْلِ الْعِلْمِ يُسَبِّحُونَ وَيُشِيرُونَ ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفُضَيْلُ يَعْنِي ابْنَ عِيَاضٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ وَزَادَ فِي الصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e1ed5b3-4325-5e3c-b63c-af6cde83c70f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '642', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ يَعْنِي ابْنَ كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ يَوْمًا ثُمَّ انْصَرَفَ فَقَالَ يَا فُلَانُ أَلَا تُحْسِنُ صَلَاتَكَ أَلَا يَنْظُرُ الْمُصَلِّي إِذَا صَلَّى كَيْفَ ‏ ‏يُصَلِّي فَإِنَّمَا ‏ ‏يُصَلِّي لِنَفْسِهِ إِنِّي وَاللَّهِ ‏ ‏لَأُبْصِرُ مِنْ وَرَائِي كَمَا أُبْصِرُ مِنْ بَيْنِ يَدَيَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d83f649e-74b9-5d5d-8c50-3f44f63cf1dd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '643', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَا هُنَا فَوَاللَّهِ مَا ‏ ‏يَخْفَى عَلَيَّ رُكُوعُكُمْ وَلَا سُجُودُكُمْ إِنِّي لَأَرَاكُمْ وَرَاءَ ظَهْرِي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89e333af-7ff8-5bcb-9e0f-359b09adafc9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '644', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَقِيمُوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ ‏ ‏إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي وَرُبَّمَا قَالَ مِنْ بَعْدِ ظَهْرِي إِذَا رَكَعْتُمْ وَسَجَدْتُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7be7510f-3f28-5eb9-8399-d2888e4bdee9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '645', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ يَعْنِي ابْنَ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ ‏ ‏إِنِّي لَأَرَاكُمْ مِنْ بَعْدِ ظَهْرِي إِذَا مَا رَكَعْتُمْ وَإِذَا مَا سَجَدْتُمْ ‏ ‏وَفِي حَدِيثِ ‏ ‏سَعِيدٍ ‏ ‏إِذَا رَكَعْتُمْ وَإِذَا سَجَدْتُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b214a02a-af38-5782-ade7-8c315e3c4918', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '646', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏ابْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَلَمَّا قَضَى الصَّلَاةَ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنِّي إِمَامُكُمْ فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ وَلَا ‏ ‏بِالِانْصِرَافِ فَإِنِّي أَرَاكُمْ أَمَامِي وَمِنْ خَلْفِي ثُمَّ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا قَالُوا وَمَا رَأَيْتَ يَا رَسُولَ اللَّهِ قَالَ رَأَيْتُ الْجَنَّةَ وَالنَّارَ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏ابْنِ فُضَيْلٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏وَلَيْسَ فِي حَدِيثِ ‏ ‏جَرِيرٍ ‏ ‏وَلَا ‏ ‏بِالِانْصِرَافِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2985a967-77a3-5204-ad66-144477d3ba34', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '647', '‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏وَأَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا ‏ ‏يَخْشَى الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يُحَوِّلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d17def0-b156-578d-ace7-2c366691f13f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '648', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏مَا يَأْمَنُ الَّذِي يَرْفَعُ رَأْسَهُ فِي صَلَاتِهِ قَبْلَ الْإِمَامِ أَنْ يُحَوِّلَ اللَّهُ صُورَتَهُ فِي صُورَةِ حِمَارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَلَّامٍ الْجُمَحِيُّ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ الرَّبِيعِ بْنِ مُسْلِمٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الرَّبِيعِ بْنِ مُسْلِمٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا ‏ ‏غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏الرَّبِيعِ بْنِ مُسْلِمٍ ‏ ‏أَنْ يَجْعَلَ اللَّهُ وَجْهَهُ وَجْهَ حِمَارٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b862a7c5-64ff-5b2e-a6f3-0a9ab175ded1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '649', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي الصَّلَاةِ أَوْ لَا تَرْجِعُ إِلَيْهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('910cdb0d-3fd7-5f10-aaf3-2a8feef9e431', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '650', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَعَمْرُو بْنُ سَوَّادٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ رَفْعِهِمْ أَبْصَارَهُمْ عِنْدَ الدُّعَاءِ فِي الصَّلَاةِ إِلَى السَّمَاءِ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('14bb2117-b292-53f5-940a-4c06f766d795', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '651', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا لِي أَرَاكُمْ رَافِعِي أَيْدِيكُمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ ‏ ‏شُمْسٍ ‏ ‏اسْكُنُوا فِي الصَّلَاةِ قَالَ ثُمَّ خَرَجَ عَلَيْنَا فَرَآنَا حَلَقًا فَقَالَ مَالِي أَرَاكُمْ ‏ ‏عِزِينَ ‏ ‏قَالَ ثُمَّ خَرَجَ عَلَيْنَا فَقَالَ أَلَا تَصُفُّونَ كَمَا تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهَا فَقُلْنَا يَا رَسُولَ اللَّهِ وَكَيْفَ تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهَا قَالَ يُتِمُّونَ الصُّفُوفَ الْأُوَلَ وَيَتَرَاصُّونَ فِي الصَّفِّ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَا ‏ ‏جَمِيعًا ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('889b5565-f4e8-5753-b6f9-1bb7b604321e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '652', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْقِبْطِيَّةِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا صَلَّيْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَا السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَأَشَارَ بِيَدِهِ إِلَى الْجَانِبَيْنِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَامَ ‏ ‏تُومِئُونَ ‏ ‏بِأَيْدِيكُمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ ‏ ‏شُمْسٍ ‏ ‏إِنَّمَا يَكْفِي أَحَدَكُمْ أَنْ يَضَعَ يَدَهُ عَلَى فَخِذِهِ ثُمَّ يُسَلِّمُ عَلَى أَخِيهِ مَنْ عَلَى يَمِينِهِ وَشِمَالِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46ab9963-f6dd-5382-a3d1-e3a6fde33693', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '653', '‏ ‏و حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ زَكَرِيَّاءَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏فُرَاتٍ يَعْنِي الْقَزَّازَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنَّا إِذَا سَلَّمْنَا قُلْنَا بِأَيْدِينَا السَّلَامُ عَلَيْكُمْ السَّلَامُ عَلَيْكُمْ فَنَظَرَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا شَأْنُكُمْ تُشِيرُونَ بِأَيْدِيكُمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ ‏ ‏شُمْسٍ ‏ ‏إِذَا سَلَّمَ أَحَدُكُمْ فَلْيَلْتَفِتْ إِلَى صَاحِبِهِ وَلَا ‏ ‏يُومِئْ ‏ ‏بِيَدِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9074af6-a123-562d-a94a-ab6b7e28d744', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '654', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ مَنَاكِبَنَا ‏ ‏فِي الصَّلَاةِ وَيَقُولُ ‏ ‏اسْتَوُوا وَلَا تَخْتَلِفُوا فَتَخْتَلِفَ قُلُوبُكُمْ لِيَلِنِي مِنْكُمْ أُولُو ‏ ‏الْأَحْلَامِ ‏ ‏وَالنُّهَى ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏فَأَنْتُمْ الْيَوْمَ أَشَدُّ اخْتِلَافًا ‏ ‏و حَدَّثَنَاه ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ خَشْرَمٍ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى يَعْنِي ابْنَ يُونُسَ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('12bc4728-135d-554d-9fed-a35cb959eb6e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '655', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏وَصَالِحُ بْنُ حَاتِمِ بْنِ وَرْدَانَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَلِنِي مِنْكُمْ أُولُو ‏ ‏الْأَحْلَامِ ‏ ‏وَالنُّهَى ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثَلَاثًا وَإِيَّاكُمْ ‏ ‏وَهَيْشَاتِ ‏ ‏الْأَسْوَاقِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3b14432-372e-5310-9cda-66d114c8d4e2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '656', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصَّفِّ مِنْ تَمَامِ الصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58fc4613-146b-5d16-94a1-757b07f343ef', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '657', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ وَهُوَ ابْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتِمُّوا الصُّفُوفَ ‏ ‏فَإِنِّي أَرَاكُمْ خَلْفَ ظَهْرِي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
