insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ba926df8-5147-5b7c-aa0a-755e37cb2877', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '659', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ الْغَطَفَانِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ ‏ ‏لَيُخَالِفَنَّ ‏ ‏اللَّهُ بَيْنَ وُجُوهِكُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06cac02a-cad8-58d5-8d7c-5ec55fc59528', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '660', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُا ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَوِّي صُفُوفَنَا حَتَّى كَأَنَّمَا يُسَوِّي بِهَا ‏ ‏الْقِدَاحَ ‏ ‏حَتَّى رَأَى أَنَّا قَدْ عَقَلْنَا عَنْهُ ثُمَّ خَرَجَ يَوْمًا فَقَامَ حَتَّى كَادَ يُكَبِّرُ فَرَأَى رَجُلًا بَادِيًا صَدْرُهُ مِنْ الصَّفِّ فَقَالَ ‏ ‏عِبَادَ اللَّهِ لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ ‏ ‏لَيُخَالِفَنَّ ‏ ‏اللَّهُ بَيْنَ وُجُوهِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ الرَّبِيعِ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1c222fa5-98ad-536e-bb67-6643763a8aed', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '661', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ ‏ ‏لَاسْتَهَمُوا ‏ ‏وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a14e3aa-88c6-5b6d-941e-2ec81e298649', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '662', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي أَصْحَابِهِ تَأَخُّرًا فَقَالَ لَهُمْ ‏ ‏تَقَدَّمُوا فَأْتَمُّوا بِي وَلْيَأْتَمَّ بِكُمْ مَنْ بَعْدَكُمْ لَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمْ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا فِي مُؤَخَّرِ الْمَسْجِدِ فَذَكَرَ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('754e3aba-fbe5-5feb-923d-c607e757d60a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '663', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ دِينَارٍ ‏ ‏وَمُحَمَّدُ بْنُ حَرْبٍ الْوَاسِطِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ تَعْلَمُونَ ‏ ‏أَوْ يَعْلَمُونَ ‏ ‏مَا فِي الصَّفِّ الْمُقَدَّمِ لَكَانَتْ قُرْعَةً ‏ ‏و قَالَ ‏ ‏ابْنُ حَرْبٍ ‏ ‏الصَّفِّ الْأَوَّلِ مَا كَانَتْ إِلَّا قُرْعَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f063c48c-3b38-534b-bc68-18257091e64f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '664', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا وَشَرُّهَا آخِرُهَا وَخَيْرُ صُفُوفِ النِّسَاءِ آخِرُهَا وَشَرُّهَا أَوَّلُهَا ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('22683a34-b808-5be4-b987-4b457d29fb83', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '665', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُ الرِّجَالَ عَاقِدِي ‏ ‏أُزُرِهِمْ ‏ ‏فِي أَعْنَاقِهِمْ مِثْلَ الصِّبْيَانِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏ ‏خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَائِلٌ يَا مَعْشَرَ النِّسَاءِ لَا تَرْفَعْنَ رُءُوسَكُنَّ حَتَّى يَرْفَعَ الرِّجَالُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83a0b554-482e-50fc-9ae8-0e5963613ea7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '666', '‏ ‏حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَ ‏ ‏سَالِمًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَأْذَنَتْ أَحَدَكُمْ امْرَأَتُهُ إِلَى الْمَسْجِدِ فَلَا يَمْنَعْهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36c5a58a-7d5a-5ba8-a40c-fce269414f5b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '667', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ إِذَا اسْتَأْذَنَّكُمْ إِلَيْهَا ‏ ‏قَالَ فَقَالَ ‏ ‏بِلَالُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَاللَّهِ لَنَمْنَعُهُنَّ قَالَ فَأَقْبَلَ عَلَيْهِ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَسَبَّهُ سَبًّا سَيِّئًا مَا سَمِعْتُهُ سَبَّهُ مِثْلَهُ قَطُّ وَقَالَ أُخْبِرُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ وَاللَّهِ لَنَمْنَعُهُنَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c52f4a38-586d-521f-98d7-ae031d62cb59', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '668', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَابْنُ إِدْرِيسَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac0204cf-36d8-5984-844a-6024380545b8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '669', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اسْتَأْذَنَكُمْ نِسَاؤُكُمْ إِلَى الْمَسَاجِدِ فَأْذَنُوا لَهُنَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6e966e1d-a14d-5f0f-9a14-c88c039b0f26', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '670', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ مِنْ الْخُرُوجِ إِلَى الْمَسَاجِدِ بِاللَّيْلِ ‏ ‏فَقَالَ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏لَا نَدَعُهُنَّ يَخْرُجْنَ فَيَتَّخِذْنَهُ ‏ ‏دَغَلًا ‏ ‏قَالَ فَزَبَرَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَقَالَ أَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ لَا نَدَعُهُنَّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ خَشْرَمٍ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a5f7f71-afe5-5933-892d-9c94fa5602be', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '671', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏وَابْنُ رَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏حَدَّثَنِي ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنُوا لِلنِّسَاءِ بِاللَّيْلِ إِلَى الْمَسَاجِدِ ‏ ‏فَقَالَ ابْنٌ لَهُ يُقَالُ لَهُ ‏ ‏وَاقِدٌ ‏ ‏إِذَنْ يَتَّخِذْنَهُ ‏ ‏دَغَلًا ‏ ‏قَالَ فَضَرَبَ فِي صَدْرِهِ وَقَالَ أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ لَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3518468d-7ec1-5015-9349-13dc4bf403d8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '672', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ حُظُوظَهُنَّ مِنْ الْمَسَاجِدِ إِذَا اسْتَأْذَنُوكُمْ ‏ ‏فَقَالَ ‏ ‏بِلَالٌ ‏ ‏وَاللَّهِ لَنَمْنَعُهُنَّ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ أَنْتَ لَنَمْنَعُهُنَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a733f37-c632-51f2-a908-b9c4c5ecd3f3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '673', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَخْرَمَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ الثَّقَفِيَّةَ ‏ ‏كَانَتْ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا شَهِدَتْ إِحْدَاكُنَّ الْعِشَاءَ فَلَا تَطَيَّبْ تِلْكَ اللَّيْلَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('669488fb-ca48-59a9-b108-ade483923c00', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '674', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ‏ ‏امْرَأَةِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَتْ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَهِدَتْ إِحْدَاكُنَّ الْمَسْجِدَ فَلَا تَمَسَّ طِيبًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('601eec51-3f86-5982-9fe4-25c82117f21c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '675', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي فَرْوَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلَا تَشْهَدْ مَعَنَا الْعِشَاءَ الْآخِرَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d84b42f9-3055-5950-b241-c37768d25b44', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '676', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏يَحْيَى وَهُوَ ابْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهَا سَمِعَتْ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏لَوْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى مَا أَحْدَثَ النِّسَاءُ لَمَنَعَهُنَّ الْمَسْجِدَ كَمَا مُنِعَتْ نِسَاءُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالَ فَقُلْتُ ‏ ‏لِعَمْرَةَ ‏ ‏أَنِسَاءُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُنِعْنَ الْمَسْجِدَ قَالَتْ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ يَعْنِي الثَّقَفِيَّ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ac4911a-b29a-5162-a45b-e689f20e8cdf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '677', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏هُشَيْمٍ ‏ ‏قَالَ ‏ ‏ابْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا ‏} ‏قَالَ نَزَلَتْ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَوَارٍ ‏ ‏بِمَكَّةَ ‏ ‏فَكَانَ إِذَا صَلَّى بِأَصْحَابِهِ رَفَعَ صَوْتَهُ بِالْقُرْآنِ فَإِذَا سَمِعَ ذَلِكَ الْمُشْرِكُونَ سَبُّوا الْقُرْآنَ وَمَنْ أَنْزَلَهُ وَمَنْ جَاءَ بِهِ فَقَالَ اللَّهُ تَعَالَى لِنَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَلَا تَجْهَرْ بِصَلَاتِكَ ‏} ‏فَيَسْمَعَ الْمُشْرِكُونَ قِرَاءَتَكَ ‏ { ‏وَلَا تُخَافِتْ بِهَا ‏} ‏عَنْ أَصْحَابِكَ أَسْمِعْهُمْ الْقُرْآنَ وَلَا تَجْهَرْ ذَلِكَ الْجَهْرَ ‏ { ‏وَابْتَغِ بَيْنَ ذَلِكَ سَبِيلًا ‏} ‏يَقُولُ بَيْنَ الْجَهْرِ ‏ ‏وَالْمُخَافَتَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b5bb6405-f54a-5a95-9ea7-bcc851cbe928', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '678', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّاءَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا ‏} ‏قَالَتْ أُنْزِلَ هَذَا فِي الدُّعَاءِ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏ح ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏قَالَ ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2384da0a-121d-5d5e-a568-c570d5adffd5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '679', '‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ ‏} ‏قَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَزَلَ عَلَيْهِ ‏ ‏جِبْرِيلُ ‏ ‏بِالْوَحْيِ كَانَ مِمَّا يُحَرِّكُ بِهِ لِسَانَهُ وَشَفَتَيْهِ فَيَشْتَدُّ عَلَيْهِ فَكَانَ ذَلِكَ يُعْرَفُ مِنْهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ ‏} ‏أَخْذَهُ ‏ { ‏إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ ‏} ‏إِنَّ عَلَيْنَا أَنْ نَجْمَعَهُ فِي صَدْرِكَ وَقُرْآنَهُ فَتَقْرَؤُهُ ‏ { ‏فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ ‏} ‏قَالَ أَنْزَلْنَاهُ فَاسْتَمِعْ لَهُ ‏ { ‏إِنَّ عَلَيْنَا بَيَانَهُ ‏} ‏أَنْ نُبَيِّنَهُ بِلِسَانِكَ فَكَانَ إِذَا أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏أَطْرَقَ ‏ ‏فَإِذَا ذَهَبَ قَرَأَهُ كَمَا وَعَدَهُ اللَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80277af1-0f56-5ffb-ba8f-d273b6e0fae8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '680', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي ‏ ‏قَوْله ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ ‏} ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَالِجُ ‏ ‏مِنْ التَّنْزِيلِ شِدَّةً كَانَ يُحَرِّكُ شَفَتَيْهِ فَقَالَ لِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَا أُحَرِّكُهُمَا كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَرِّكُهُمَا فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏أَنَا أُحَرِّكُهُمَا كَمَا كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُحَرِّكُهُمَا فَحَرَّكَ شَفَتَيْهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ ‏} ‏قَالَ جَمْعَهُ فِي صَدْرِكَ ثُمَّ تَقْرَؤُهُ ‏ { ‏فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ ‏} ‏قَالَ فَاسْتَمِعْ وَأَنْصِتْ ثُمَّ إِنَّ عَلَيْنَا أَنْ تَقْرَأَهُ قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏اسْتَمَعَ فَإِذَا انْطَلَقَ ‏ ‏جِبْرِيلُ ‏ ‏قَرَأَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا أَقْرَأَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7743a154-f488-5815-b01d-cde8b18bf3cc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '681', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْجِنِّ وَمَا رَآهُمْ انْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَائِفَةٍ مِنْ أَصْحَابِهِ ‏ ‏عَامِدِينَ ‏ ‏إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْهِمْ الشُّهُبُ فَرَجَعَتْ الشَّيَاطِينُ إِلَى قَوْمِهِمْ فَقَالُوا مَا لَكُمْ قَالُوا حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ قَالُوا مَا ذَاكَ إِلَّا مِنْ شَيْءٍ حَدَثَ فَاضْرِبُوا مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا فَانْظُرُوا مَا هَذَا الَّذِي حَالَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ فَانْطَلَقُوا يَضْرِبُونَ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا فَمَرَّ النَّفَرُ الَّذِينَ أَخَذُوا نَحْوَ ‏ ‏تِهَامَةَ ‏ ‏وَهُوَ بِنَخْلٍ ‏ ‏عَامِدِينَ ‏ ‏إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِأَصْحَابِهِ صَلَاةَ الْفَجْرِ فَلَمَّا سَمِعُوا الْقُرْآنَ اسْتَمَعُوا لَهُ وَقَالُوا هَذَا الَّذِي حَالَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ فَرَجَعُوا إِلَى قَوْمِهِمْ فَقَالُوا يَا قَوْمَنَا ‏ { ‏إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا ‏} ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَى نَبِيِّهِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِنْ الْجِنِّ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88e8b202-2853-53d7-82f5-7dda0d26d1c6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '682', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَلْقَمَةَ ‏ ‏هَلْ كَانَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏شَهِدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ قَالَ فَقَالَ ‏ ‏عَلْقَمَةُ ‏ ‏أَنَا سَأَلْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَقُلْتُ هَلْ شَهِدَ أَحَدٌ مِنْكُمْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ قَالَ لَا وَلَكِنَّا كُنَّا مَعَ رَسُولِ اللَّهِ ذَاتَ لَيْلَةٍ فَفَقَدْنَاهُ فَالْتَمَسْنَاهُ فِي الْأَوْدِيَةِ ‏ ‏وَالشِّعَابِ ‏ ‏فَقُلْنَا ‏ ‏اسْتُطِيرَ ‏ ‏أَوْ ‏ ‏اغْتِيلَ ‏ ‏قَالَ فَبِتْنَا بِشَرِّ لَيْلَةٍ بَاتَ بِهَا قَوْمٌ فَلَمَّا أَصْبَحْنَا إِذَا هُوَ ‏ ‏جَاءٍ مِنْ قِبَلَ ‏ ‏حِرَاءٍ ‏ ‏قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ فَقَدْنَاكَ فَطَلَبْنَاكَ فَلَمْ نَجِدْكَ فَبِتْنَا بِشَرِّ لَيْلَةٍ بَاتَ بِهَا قَوْمٌ فَقَالَ ‏ ‏أَتَانِي دَاعِي الْجِنِّ فَذَهَبْتُ مَعَهُ فَقَرَأْتُ عَلَيْهِمْ الْقُرْآنَ قَالَ فَانْطَلَقَ بِنَا فَأَرَانَا آثَارَهُمْ وَآثَارَ نِيرَانِهِمْ وَسَأَلُوهُ الزَّادَ فَقَالَ لَكُمْ كُلُّ عَظْمٍ ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ يَقَعُ فِي أَيْدِيكُمْ أَوْفَرَ مَا يَكُونُ لَحْمًا وَكُلُّ بَعْرَةٍ عَلَفٌ لِدَوَابِّكُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَسْتَنْجُوا بِهِمَا فَإِنَّهُمَا طَعَامُ إِخْوَانِكُمْ ‏ ‏و حَدَّثَنِيهِ ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏بِهَذَا الْإِسْنَادِ إِلَى قَوْلِهِ وَآثَارَ نِيرَانِهِمْ ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏وَسَأَلُوهُ الزَّادَ وَكَانُوا مِنْ جِنِّ الْجَزِيرَةِ إِلَى آخِرِ الْحَدِيثِ مِنْ قَوْلِ ‏ ‏الشَّعْبِيِّ ‏ ‏مُفَصَّلًا مِنْ حَدِيثِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَآثَارَ نِيرَانِهِمْ وَلَمْ يَذْكُرْ مَا بَعْدَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6548ae81-829f-5cd6-a747-8e5ad5e745fd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '683', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمْ أَكُنْ لَيْلَةَ الْجِنِّ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوَدِدْتُ أَنِّي كُنْتُ مَعَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24f978e9-cc6c-5432-bfad-0ee7ca825d4a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '684', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مُحَمَّدٍ الْجَرْمِيُّ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏مَعْنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏مَسْرُوقًا ‏ ‏مَنْ ‏ ‏آذَنَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْجِنِّ لَيْلَةَ اسْتَمَعُوا الْقُرْآنَ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبُوكَ ‏ ‏يَعْنِي ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏أَنَّهُ ‏ ‏آذَنَتْهُ ‏ ‏بِهِمْ شَجَرَةٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c8d7ee49-8c1a-5e17-8b14-717ac0ee22af', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '685', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ يَعْنِي الصَّوَّافَ ‏ ‏عَنْ ‏ ‏يَحْيَى وَهُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِنَا فَيَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَتَيْنِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَكَانَ يُطَوِّلُ الرَّكْعَةَ الْأُولَى مِنْ الظُّهْرِ وَيُقَصِّرُ الثَّانِيَةَ وَكَذَلِكَ فِي الصُّبْحِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('22485f72-dc70-51fa-9615-cc95c91ad780', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '686', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَالْعَصْرِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَةٍ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bbeca970-aba5-5086-8f9e-099a1786c4d6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '687', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏هُشَيْمٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَحْزِرُ ‏ ‏قِيَامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الظُّهْرِ وَالْعَصْرِ ‏ ‏فَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ قَدْرَ قِرَاءَةِ ‏ ‏الم تَنْزِيلُ السَّجْدَةِ ‏ ‏وَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الْأُخْرَيَيْنِ قَدْرَ النِّصْفِ مِنْ ذَلِكَ ‏ ‏وَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الْعَصْرِ عَلَى قَدْرِ قِيَامِهِ فِي الْأُخْرَيَيْنِ مِنْ الظُّهْرِ وَفِي الْأُخْرَيَيْنِ مِنْ الْعَصْرِ عَلَى النِّصْفِ مِنْ ذَلِكَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي رِوَايَتِهِ ‏ ‏الم تَنْزِيلُ ‏ ‏وَقَالَ قَدْرَ ثَلَاثِينَ آيَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9fb72dd1-4246-5587-8393-3ee71be05c5c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '688', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الظُّهْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ فِي كُلِّ رَكْعَةٍ قَدْرَ ثَلَاثِينَ آيَةً وَفِي الْأُخْرَيَيْنِ قَدْرَ خَمْسَ عَشْرَةَ آيَةً ‏ ‏أَوْ قَالَ نِصْفَ ذَلِكَ ‏ ‏وَفِي الْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ فِي كُلِّ رَكْعَةٍ قَدْرَ قِرَاءَةِ خَمْسَ عَشْرَةَ آيَةً وَفِي الْأُخْرَيَيْنِ قَدْرَ نِصْفِ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e5d6e30-2e68-58b7-b3e2-fe991dd629b5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '689', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏أَنَّ أَهْلَ ‏ ‏الْكُوفَةِ ‏ ‏شَكَوْا ‏ ‏سَعْدًا ‏ ‏إِلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَذَكَرُوا مِنْ صَلَاتِهِ فَأَرْسَلَ إِلَيْهِ ‏ ‏عُمَرُ ‏ ‏فَقَدِمَ عَلَيْهِ فَذَكَرَ لَهُ مَا عَابُوهُ بِهِ مِنْ أَمْرِ الصَّلَاةِ فَقَالَ ‏ ‏إِنِّي لَأُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏أَخْرِمُ ‏ ‏عَنْهَا إِنِّي لَأَرْكُدُ بِهِمْ فِي الْأُولَيَيْنِ وَأَحْذِفُ فِي الْأُخْرَيَيْنِ فَقَالَ ذَاكَ الظَّنُّ بِكَ ‏ ‏أَبَا إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88c36d82-76f6-50e4-a81f-c37a9cb68e26', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '690', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لِسَعْدٍ ‏ ‏قَدْ شَكَوْكَ فِي كُلِّ شَيْءٍ حَتَّى فِي الصَّلَاةِ قَالَ ‏ ‏أَمَّا أَنَا فَأَمُدُّ فِي الْأُولَيَيْنِ وَأَحْذِفُ فِي الْأُخْرَيَيْنِ وَمَا ‏ ‏آلُو ‏ ‏مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ذَاكَ الظَّنُّ بِكَ ‏ ‏أَوْ ذَاكَ ظَنِّي بِكَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏وَأَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏بِمَعْنَى حَدِيثِهِمْ وَزَادَ فَقَالَ تُعَلِّمُنِي الْأَعْرَابُ بِالصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8caa7413-fd76-5279-869c-4688e11a8076', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '691', '‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ رُشَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ وَهُوَ ابْنُ عَبْدِ العَزِيزِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏قَزْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَقَدْ كَانَتْ صَلَاةُ الظُّهْرِ تُقَامُ فَيَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَيَقْضِي حَاجَتَهُ ثُمَّ يَتَوَضَّأُ ثُمَّ يَأْتِي وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّكْعَةِ الْأُولَى مِمَّا يُطَوِّلُهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a47b57c-c292-5029-a75a-b902f5ff0f08', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '692', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَزْعَةُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏وَهُوَ ‏ ‏مَكْثُورٌ عَلَيْهِ ‏ ‏فَلَمَّا تَفَرَّقَ النَّاسُ عَنْهُ قُلْتُ إِنِّي لَا أَسْأَلُكَ عَمَّا يَسْأَلُكَ هَؤُلَاءِ عَنْهُ قُلْتُ أَسْأَلُكَ عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا لَكَ فِي ذَاكَ مِنْ خَيْرٍ فَأَعَادَهَا عَلَيْهِ فَقَالَ كَانَتْ صَلَاةُ الظُّهْرِ تُقَامُ فَيَنْطَلِقُ أَحَدُنَا إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَيَقْضِي حَاجَتَهُ ثُمَّ يَأْتِي أَهْلَهُ فَيَتَوَضَّأُ ثُمَّ يَرْجِعُ إِلَى الْمَسْجِدِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّكْعَةِ الْأُولَى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a1ae6cd-f3ed-533a-ba97-a75e4cd6c7f1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '693', '‏ ‏و حَدَّثَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَتَقَارَبَا فِي اللَّفْظِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ سُفْيَانَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْمُسَيَّبِ الْعَابِدِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ ‏ ‏بِمَكَّةَ ‏ ‏فَاسْتَفْتَحَ سُورَةَ ‏ ‏الْمُؤْمِنِينَ ‏ ‏حَتَّى جَاءَ ذِكْرُ ‏ ‏مُوسَى ‏ ‏وَهَارُونَ ‏ ‏أَوْ ذِكْرُ ‏ ‏عِيسَى ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏يَشُكُّ أَوْ اخْتَلَفُوا عَلَيْهِ ‏ ‏أَخَذَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَعْلَةٌ فَرَكَعَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ السَّائِبِ ‏ ‏حَاضِرٌ ذَلِكَ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏فَحَذَفَ فَرَكَعَ ‏ ‏وَفِي حَدِيثِهِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏وَلَمْ يَقُلْ ‏ ‏ابْنِ الْعَاصِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32fd760c-03d3-5b4c-9bf5-3c0ca0c3d9bc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '694', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ سَرِيعٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْفَجْرِ ‏ ‏وَاللَّيْلِ إِذَا ‏ ‏عَسْعَسَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('02ee09c6-4371-5439-88cb-058caed16d04', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '695', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ فُضَيْلُ بْنُ حُسَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ وَصَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَ ‏ ‏ق وَالْقُرْآنِ الْمَجِيدِ ‏ ‏حَتَّى قَرَأَ ‏ { ‏وَالنَّخْلَ ‏ ‏بَاسِقَاتٍ ‏ } ‏قَالَ فَجَعَلْتُ أُرَدِّدُهَا وَلَا أَدْرِي مَا قَالَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6773737c-004c-546d-b58a-ac144bc930dd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '696', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏وَابْنُ عُيَيْنَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ مَالِكٍ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْفَجْرِ ‏ { ‏وَالنَّخْلَ ‏ ‏بَاسِقَاتٍ ‏ ‏لَهَا ‏ ‏طَلْعٌ ‏ ‏نَضِيدٌ ‏ }', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0c03ba73-000e-5bd3-9ec8-aa378a121b9b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '697', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ فَقَرَأَ فِي أَوَّلِ رَكْعَةٍ ‏ { ‏وَالنَّخْلَ ‏ ‏بَاسِقَاتٍ ‏ ‏لَهَا ‏ ‏طَلْعٌ ‏ ‏نَضِيدٌ ‏ } ‏وَرُبَّمَا قَالَ ‏ ‏ق ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2d704a71-b525-5db3-9f29-50a3f28a1bab', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '698', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فِي الْفَجْرِ ‏ ‏بِق وَالْقُرْآنِ الْمَجِيدِ ‏ ‏وَكَانَ صَلَاتُهُ بَعْدُ تَخْفِيفًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('478d9f4e-9669-5614-8770-3e942432399f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '699', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِابْنِ رَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏جَابِرَ بْنَ سَمُرَةَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏يُخَفِّفُ الصَّلَاةَ وَلَا ‏ ‏يُصَلِّي صَلَاةَ هَؤُلَاءِ قَالَ وَأَنْبَأَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فِي الْفَجْرِ ‏ ‏بِق وَالْقُرْآنِ ‏ ‏وَنَحْوِهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('979d1ce3-970b-5d5e-8ccb-e647621ca872', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '700', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ ‏ ‏بِاللَّيْلِ إِذَا ‏ ‏يَغْشَى ‏ ‏وَفِي الْعَصْرِ نَحْوَ ذَلِكَ وَفِي الصُّبْحِ أَطْوَلَ مِنْ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ec2d0ff-e347-5c49-a3c3-0ea5986a0ba0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '701', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَفِي الصُّبْحِ بِأَطْوَلَ مِنْ ذَلِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('45c21b16-d19a-5f3d-b156-8ff1cdce5e1f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '702', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مِنْ السِّتِّينَ إِلَى الْمِائَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b75089f-eae1-543d-a641-0f63bfc6fba2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '703', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْفَجْرِ مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ آيَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6139307-1165-578a-ac2d-f28b7bffb90a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '704', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ ‏ ‏سَمِعَتْهُ وَهُوَ ‏ ‏يَقْرَأُ ‏ ‏وَالْمُرْسَلَاتِ ‏ ‏عُرْفًا ‏ ‏فَقَالَتْ يَا بُنَيَّ لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ إِنَّهَا لَآخِرُ مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فِي الْمَغْرِبِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَزَادَ فِي حَدِيثِ ‏ ‏صَالِحٍ ‏ ‏ثُمَّ مَا صَلَّى بَعْدُ حَتَّى قَبَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
